template.script:
(function () {
    function aqToggleLastPage() {
        try {
            var qs = window.location.search || '';
            var get = function (k) {
                var m = qs.match(new RegExp('[?&]' + k + '=(\\d+)'));
                return m ? parseInt(m[1], 10) : 0;
            };
            var page = get('page');
            var topage = get('topage');
            var isLast = page && topage && page === topage;
            var els = document.getElementsByClassName('aq-lastpage-only');
            for (var i = 0; i < els.length; i++) {
                els[i].style.display = isLast ? 'block' : 'none';
            }
        } catch (e) { /* noop */ }
    }
    if (document.readyState !== 'loading') { aqToggleLastPage(); }
    else { document.addEventListener('DOMContentLoaded', aqToggleLastPage); }
    window.addEventListener('load', aqToggleLastPage);
})();
